def reverse(head):
    prev = None
    while head:
        head.next, prev, head = prev, head, head.next
    return prev

def lis(a):
    dp = [1]*len(a)
    for i in range(len(a)):
        for j in range(i):
            if a[j] < a[i]: dp[i] = max(dp[i], dp[j]+1)
    return max(dp, default=0)
